query {
  repository(owner: "OWNER", name: "REPO") {
    vulnerabilityAlerts(first: 100, states: OPEN) {
      nodes {
        createdAt
        securityVulnerability {
          package { name }
          severity
          vulnerableVersionRange
          advisory { ghsaId publishedAt }
        }
      }
    }
  }
}
